             [('Story opening', '90 seconds of personal story.', {'fix': 'Shorten'}), ('Problem', '20 seconds with one customer quote.', {'fix': 'Keep|Lengthen'}),
              ('Product demo', '10 seconds — no screenshots shown.', {'fix': 'Lengthen'}), ('Ask', '15 seconds, clear amount and use.', {'fix': 'Keep'})],
             'Marcus Lee, pitch coach', 'You ran 4 minutes. What will you cut?',
